"""
Tests for cgate.gate — the assembled, decision-ready file.

This is the end-to-end shape of the product: a pursuit on the register, a
solicitation on disk, and fifteen adjudicated items in which nothing is
silently absent.
"""

from __future__ import annotations

import json
import os

import docx
import pytest

from cgate import db, gate, registry, screen
from cgate.model import Status

# Generated by `python examples/make_sample.py`. A missing file is a failure,
# never a skip: a silently skipped gate test proves nothing.
SOLICITATION = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..",
                            "examples", "blind-rfp", "blind-rfp-schools.docx")

FIRM = "Example Engineering Ltd"


@pytest.fixture()
def conn(tmp_path):
    c = db.connect(str(tmp_path / "register.db"))
    yield c
    c.close()


@pytest.fixture()
def snapshot(tmp_path):
    """A local screening dataset carrying a listing of the bidding firm."""
    records = [{
        "id": "sanctions-example", "caption": "Example Engineering Ltd",
        "schema": "Company", "datasets": ["example_exclusion"],
        "properties": {"name": ["Example Engineering Ltd"],
                       "topics": ["debarment"], "country": ["xx"]},
    }]
    p = tmp_path / "snap.json"
    p.write_text(json.dumps(records), encoding="utf-8")
    return screen.ScreeningConfig(snapshot=str(p), dataset="debarment")


@pytest.fixture()
def pursuit(conn):
    client = db.upsert_entity(conn, "Example Agency", "authority", jurisdiction="INT",
                              registration_no="UN-1946", created_by="t")
    sub = db.upsert_entity(conn, "Shared Subcontractor LLC", jurisdiction="XX",
                           created_by="t")
    db.open_pursuit(conn, "P-1", client, "Schools detailed design",
                    submission_deadline="2026-12-01", notified_by="BD Manager",
                    tender_reference="RFP-2026/117", jurisdiction="XX",
                    notified_at="2026-08-03T09:00:00")
    db.add_party(conn, "P-1", sub, "subcontractor")
    return {"pursuit": "P-1", "sub": sub, "client": client}


def build(conn, snapshot, **kw):
    return gate.assemble(
        conn, "P-1", [SOLICITATION], firm_name=FIRM,
        screening_config=snapshot, as_of="2026-08-10",
        checklist_path="config/checklist.example.yaml", **kw)


# ---------------------------------------------------------------------------


def test_every_item_is_adjudicated(conn, pursuit, snapshot):
    gf = build(conn, snapshot)
    assert sorted(gf.statuses) == list(range(1, 16))
    assert all(isinstance(s, str) for s in gf.statuses.values())


def test_a_listing_of_the_bidding_firm_flags_item_3(conn, pursuit, snapshot):
    """A listing of the bidding firm must always be reported.

    The offline scorer is deliberately blunt, so a real match on a name written
    two different ways may land as `partial_name_match` rather than `any_match`.
    Both escalate, and that is the property worth asserting: the tool is not
    required to be certain, it is required not to stay quiet.
    """
    gf = build(conn, snapshot)
    assert gf.statuses[3] == Status.FLAG.value
    assert set(gf.bundle["3"]["triggers"]) & {"any_match", "partial_name_match"}
    assert gf.screenings[0].hits[0]["datasets"] == ["example_exclusion"]


def test_high_risk_jurisdiction_flags_item_5(conn, pursuit, snapshot):
    """An example country code is high-risk by default per SOP-3.7."""
    gf = build(conn, snapshot)
    assert gf.bundle["5"]["triggers"] == ["high_risk_jurisdiction"]
    assert gf.statuses[5] == Status.FLAG.value


def test_a_jurisdiction_absent_from_the_table_is_not_treated_as_low_risk(conn, pursuit, snapshot):
    conn.execute("UPDATE pursuit SET jurisdiction = 'FR' WHERE id = 'P-1'")
    gf = build(conn, snapshot)
    assert gf.bundle["5"]["triggers"] == ["jurisdiction_not_in_table"]
    assert gf.statuses[5] == Status.FLAG.value


def test_a_missing_declaration_blocks_and_says_so(conn, pursuit, snapshot):
    gf = build(conn, snapshot)
    reasons = gate.blocking_reasons(gf)
    assert any("declaration missing" in r for r in reasons)
    assert gf.statuses[6] == Status.FLAG.value


def test_item_6_reaches_a_human_once_all_four_mechanisms_report(conn, pursuit, snapshot, tmp_path):
    """The full item 6 contract: four mechanisms, then a person decides.

    registry.evidence() alone cannot satisfy item 6 (see test_registry.py).
    With the declaration filed, attendance recorded and a shared-content scan
    run, the evidence is complete — and item 6 still stops at requires_human,
    because it is marked never_auto_clear.
    """
    registry.sign_declaration(conn, "P-1", pursuit["sub"], "subcontractor",
                              "DECL-1", signatory="A. Rowan", signed_at="2026-08-05")
    db.record_attendance(conn, "P-1", "site_visit", "2026-08-04",
                         attendee_name="Shared Subcontractor LLC",
                         attendee_entity=pursuit["sub"], recorded_by="BD Manager")

    ours = tmp_path / "ours.docx"
    theirs = tmp_path / "theirs.docx"
    for path, text in ((ours, "Our own methodology, written independently."),
                       (theirs, "Their material, entirely unrelated content.")):
        d = docx.Document()
        d.add_paragraph(text)
        d.core_properties.author = "Someone" if path is ours else "Someone Else"
        d.save(str(path))

    gf = build(conn, snapshot, submission_path=str(ours),
               third_party_material=[str(theirs)])

    assert gf.bundle["6"]["triggers"] == []
    assert gf.statuses[6] == Status.REQUIRES_HUMAN.value
    assert gf.conflict_scans and gf.conflict_scans[0].triggers == []


def test_shared_content_between_submissions_flags_item_6(conn, pursuit, snapshot, tmp_path):
    """Content-sharing, reproduced: identical methodology, same author."""
    registry.sign_declaration(conn, "P-1", pursuit["sub"], "subcontractor",
                              "DECL-1", signatory="A. Rowan", signed_at="2026-08-05")
    shared = "The consultant shall mobilise a topographic survey team. " * 25
    ours, theirs = tmp_path / "ours.docx", tmp_path / "theirs.docx"
    for path in (ours, theirs):
        d = docx.Document()
        d.add_paragraph(shared)
        d.core_properties.author = "S. Quill"
        d.save(str(path))

    gf = build(conn, snapshot, submission_path=str(ours),
               third_party_material=[str(theirs)])

    triggers = gf.bundle["6"]["triggers"]
    assert "content_similarity_above_threshold" in triggers
    assert "metadata_origin_match" in triggers
    assert gf.statuses[6] == Status.FLAG.value


def test_a_failed_screening_appears_in_blocking_reasons(conn, pursuit, tmp_path):
    missing = screen.ScreeningConfig(snapshot=str(tmp_path / "absent.json"))
    gf = build(conn, missing)
    reasons = gate.blocking_reasons(gf)
    assert any("not screened" in r for r in reasons)
    assert gf.statuses[3] == Status.FLAG.value


def test_items_13_and_14_stay_unresolved_with_a_stated_reason(conn, pursuit, snapshot):
    gf = build(conn, snapshot)
    assert gf.statuses[13] == Status.UNRESOLVED.value
    assert gf.statuses[14] == Status.UNRESOLVED.value
    assert any("HR and credential source records" in n for n in gf.notes)


def test_attestations_are_carried_through(conn, pursuit, snapshot):
    att = {"10": {"attestation": {"signed": True, "attestor": "BD Manager",
                                  "date": "2026-08-06"}}}
    gf = build(conn, snapshot, attestations=att)
    assert gf.statuses[10] == Status.EVIDENCE_PRESENT.value
    assert gf.statuses[11] == Status.UNRESOLVED.value      # not supplied


def test_item_2_is_incomplete_without_a_source_url(conn, pursuit, snapshot):
    """Hashing the file proves which bytes were read, not where they came from."""
    gf = build(conn, snapshot)
    assert gf.bundle["2"]["source_snapshot_hash"]
    assert "solicitation_source_url" not in gf.bundle["2"]
    assert gf.statuses[2] == Status.FLAG.value

    gf2 = build(conn, snapshot, source_url="https://procurement.example.invalid/notice/123")
    assert gf2.statuses[2] == Status.EVIDENCE_PRESENT.value


def test_clock_breaches_reach_the_blocking_list(conn, pursuit, snapshot):
    conn.execute("UPDATE pursuit SET submission_deadline = '2026-08-06' WHERE id='P-1'")
    gf = build(conn, snapshot)
    assert gf.clocks["breaches"]
    assert any("Clock breach" in r for r in gate.blocking_reasons(gf))


def test_assembly_writes_no_decision(conn, pursuit, snapshot):
    """The whole point. Assembly produces a file; it never determines anything."""
    build(conn, snapshot)
    assert conn.execute("SELECT COUNT(*) FROM decision").fetchone()[0] == 0


def test_the_gate_file_can_be_recorded_and_the_chain_still_verifies(conn, pursuit, snapshot):
    gf = build(conn, snapshot)
    db.record_review(conn, "P-1", gf.review)
    assert db.verify_chain(conn).ok
    rows = conn.execute(
        "SELECT COUNT(*) FROM check_result WHERE pursuit_id='P-1'").fetchone()[0]
    assert rows == 15


def test_unknown_pursuit_is_refused(conn, snapshot):
    with pytest.raises(ValueError, match="no such pursuit"):
        gate.assemble(conn, "P-NOPE", [SOLICITATION], firm_name=FIRM,
                      screening_config=snapshot)
